<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue';
import { useRouter } from 'vue-router';
import { api } from '@/app/runtime';
import { useSessionStore } from '@/stores/session';
import { useSettingsStore } from '@/stores/settings';
import { useAsync } from '@/composables/useAsync';
import type { JsonObject } from '@/api/types';
const router = useRouter(); const session = useSessionStore(); const settings = useSettingsStore(); const query = useAsync<JsonObject>(); const security = useAsync<JsonObject>(); const securityEnabled = computed(() => security.data.value?.enabled === true); const edit = ref(false); const error = ref(''); const saving = ref(false); const form = reactive({ nickname: '', bio: '', region: '', socialMedia: '', showRegistrations: false });
onMounted(async () => { const profile = await query.run(() => api.profile.get()); if (profile) Object.assign(form, profile); await security.run(() => api.security.get()); });
async function save() { error.value = ''; saving.value = true; try { const result = await api.profile.save({ ...form }); if (result.ok === false) throw new Error(String(result.error || '保存失败')); session.applyUser({ ...session.user, ...form }); edit.value = false; } catch (reason) { error.value = reason instanceof Error ? reason.message : String(reason); } finally { saving.value = false; } }
async function logout() { await api.auth.logout(); session.clear(); await router.replace('/login'); }
</script>
<template><section class="page"><header class="topbar"><h1>个人资料</h1><button class="text-action" @click="logout">退出登录</button></header><div v-if="query.loading" class="state">正在加载…</div><div v-else-if="query.error" class="state error">{{ query.error.value?.message }}<button @click="query.run(() => api.profile.get())">重试</button></div><template v-else><article class="card"><h2>{{ session.user.nickname || session.user.username }}</h2><p class="muted">{{ session.user.email }}</p><p class="muted">{{ session.user.roleLabel || session.user.role }} · {{ session.user.status }}</p></article><form v-if="edit" class="card form" @submit.prevent="save"><label>昵称<input v-model="form.nickname" maxlength="20"></label><label>简介<textarea v-model="form.bio" maxlength="200"></textarea></label><label>地区<input v-model="form.region"></label><label>社交链接<input v-model="form.socialMedia"></label><label><input v-model="form.showRegistrations" type="checkbox">公开报名记录</label><p v-if="error" class="error">{{ error }}</p><button class="cta" :disabled="saving">保存</button></form><button v-else class="cta ghost" :disabled="session.user.can?.profile === false" @click="edit = true">编辑资料</button><article class="card"><h2>外观</h2><label>模式<select :value="settings.mode" @change="settings.setMode(($event.target as HTMLSelectElement).value as 'auto' | 'light' | 'dark')"><option value="auto">跟随系统</option><option value="light">浅色</option><option value="dark">深色</option></select></label></article><article class="card"><h2>安全</h2><p>两步验证：{{ securityEnabled ? '已开启' : '未开启' }}</p><p v-if="security.error" class="error">{{ security.error.value?.message }}</p><button class="cta ghost" @click="router.push('/security')">管理安全设置</button></article></template></section></template>
